CREATE TABLE public.document_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES public.companies(id), name text NOT NULL, type text NOT NULL DEFAULT 'declaracao', body_html text NOT NULL, default_format text NOT NULL DEFAULT 'A4', signature_mode text NOT NULL DEFAULT 'empresa', is_active boolean NOT NULL DEFAULT true, is_system_default boolean NOT NULL DEFAULT false, source_template_id uuid REFERENCES public.document_templates(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, UNIQUE(company_id,source_template_id));
GRANT SELECT ON public.document_templates TO authenticated; GRANT ALL ON public.document_templates TO service_role;
ALTER TABLE public.document_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY documentos_ler ON public.document_templates FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL AND (company_id IS NULL AND is_system_default OR company_id=public.get_user_company_id(auth.uid())));
CREATE TABLE public.document_print_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), template_id uuid REFERENCES public.document_templates(id) ON DELETE SET NULL, template_name text NOT NULL, attendance_id uuid NOT NULL REFERENCES public.attendance_orders(id), printed_by uuid NOT NULL, printed_at timestamptz NOT NULL DEFAULT now(), format text NOT NULL);
GRANT SELECT ON public.document_print_logs TO authenticated; GRANT ALL ON public.document_print_logs TO service_role;
ALTER TABLE public.document_print_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY documentos_logs_ler ON public.document_print_logs FOR SELECT TO authenticated USING (company_id=public.get_user_company_id(auth.uid()) AND public.has_role(auth.uid(),'company_admin'));
CREATE FUNCTION public.documento_modelo_salvar(_id uuid,_dados jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE c uuid:=public.get_user_company_id(auth.uid()); t public.document_templates; r uuid; b text:=_dados->>'body_html'; v text; k text; permitido text[]:=ARRAY['paciente_nome','paciente_data_nascimento','paciente_idade','paciente_sexo','paciente_cpf','paciente_rg','paciente_telefone','paciente_endereco','responsavel_nome','responsavel_cpf','atendimento_codigo','atendimento_data','atendimento_hora','atendimento_hora_inicio','atendimento_hora_fim','convenio','medico_solicitante','unidade_origem','lista_exames','empresa_nome','empresa_cnpj','empresa_cidade','empresa_uf','responsavel_tecnico_nome','responsavel_tecnico_registro','data_extenso','dia_semana','data_impressao','hora_impressao','local_data_extenso'];
BEGIN
IF auth.uid() IS NULL OR c IS NULL OR NOT(public.has_role(auth.uid(),'company_admin') OR private.is_super_admin()) THEN RAISE EXCEPTION 'Sem permissão para editar modelos'; END IF;
IF length(btrim(coalesce(_dados->>'name',''))) NOT BETWEEN 2 AND 120 OR length(coalesce(b,'')) NOT BETWEEN 1 AND 100000 OR _dados->>'type' NOT IN ('declaracao','termo','outro') OR _dados->>'default_format' NOT IN ('A4','A5') OR _dados->>'signature_mode' NOT IN ('paciente','responsavel','empresa','paciente_empresa','responsavel_empresa','paciente_responsavel') THEN RAISE EXCEPTION 'Dados do modelo inválidos'; END IF;
FOR v IN SELECT (regexp_matches(b,'\{\{([^{}]+)\}\}','g'))[1] LOOP IF NOT(v=ANY(permitido)) THEN RAISE EXCEPTION 'Campo {{%}} não existe',v; END IF; END LOOP;
-- Reject all markup except the rich editor's safe, strictly bounded vocabulary.
k:=regexp_replace(b,'</?(p|h1|h2|h3|strong|b|em|i|u|ul|ol|li|br|span)( style="(text-align: (left|right|center|justify);?|font-size: (8|9|10|11|12|14|16|18|20|24|28|32)pt;?|text-align: (left|right|center|justify); font-size: (8|9|10|11|12|14|16|18|20|24|28|32)pt;?)")?\s*/?>','','gi');
IF k ~ '[<>]' OR b ~* '(javascript:|data:|on[a-z]+\s*=)' THEN RAISE EXCEPTION 'Conteúdo HTML não permitido'; END IF;
IF _id IS NOT NULL THEN SELECT * INTO t FROM public.document_templates WHERE id=_id FOR UPDATE; IF NOT FOUND OR (t.company_id IS NOT NULL AND t.company_id<>c) THEN RAISE EXCEPTION 'Modelo indisponível'; END IF; END IF;
IF t.is_system_default THEN SELECT id INTO r FROM public.document_templates WHERE company_id=c AND source_template_id=t.id; ELSE r:=_id; END IF;
r:=coalesce(r,gen_random_uuid());
INSERT INTO public.document_templates(id,company_id,name,type,body_html,default_format,signature_mode,is_active,source_template_id,created_by) VALUES(r,c,btrim(_dados->>'name'),_dados->>'type',b,_dados->>'default_format',_dados->>'signature_mode',coalesce((_dados->>'is_active')::boolean,true),CASE WHEN t.is_system_default THEN t.id ELSE t.source_template_id END,auth.uid()) ON CONFLICT(id) DO UPDATE SET name=excluded.name,type=excluded.type,body_html=excluded.body_html,default_format=excluded.default_format,signature_mode=excluded.signature_mode,is_active=excluded.is_active,updated_at=now(); RETURN r;
END $$;
REVOKE ALL ON FUNCTION public.documento_modelo_salvar(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.documento_modelo_salvar(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.documento_modelo_excluir(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=public.get_user_company_id(auth.uid()); BEGIN IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'company_admin') OR private.is_super_admin()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; DELETE FROM public.document_templates WHERE id=_id AND company_id=c AND NOT is_system_default; IF NOT FOUND THEN RAISE EXCEPTION 'Modelo indisponível'; END IF; END $$;
REVOKE ALL ON FUNCTION public.documento_modelo_excluir(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.documento_modelo_excluir(uuid) TO authenticated;
CREATE FUNCTION public.documento_impressao_registrar(_modelo uuid,_atendimento uuid,_formato text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=public.get_user_company_id(auth.uid()); t public.document_templates; BEGIN IF auth.uid() IS NULL OR c IS NULL OR _formato NOT IN ('A4','A5') THEN RAISE EXCEPTION 'Impressão inválida'; END IF; IF NOT EXISTS(SELECT 1 FROM public.attendance_orders WHERE id=_atendimento AND company_id=c) THEN RAISE EXCEPTION 'Atendimento indisponível'; END IF; SELECT * INTO t FROM public.document_templates WHERE id=_modelo AND is_active AND (company_id=c OR company_id IS NULL AND is_system_default); IF NOT FOUND OR (t.is_system_default AND EXISTS(SELECT 1 FROM public.document_templates WHERE company_id=c AND source_template_id=t.id)) THEN RAISE EXCEPTION 'Modelo indisponível'; END IF; INSERT INTO public.document_print_logs(company_id,template_id,template_name,attendance_id,printed_by,format) VALUES(c,t.id,t.name,_atendimento,auth.uid(),_formato); END $$;
REVOKE ALL ON FUNCTION public.documento_impressao_registrar(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.documento_impressao_registrar(uuid,uuid,text) TO authenticated;
CREATE INDEX document_templates_empresa ON public.document_templates(company_id); CREATE INDEX document_logs_empresa ON public.document_print_logs(company_id,printed_at);